import{_ as e,c as l,a2 as r,o as i}from"./chunks/framework.BQmytedh.js";const u=JSON.parse('{"title":"药物","description":"","frontmatter":{},"headers":[],"relativePath":"护肤/痤疮/哔站_皮科医生魏小博/药物.md","filePath":"护肤/痤疮/哔站_皮科医生魏小博/药物.md","lastUpdated":null}'),t={name:"护肤/痤疮/哔站_皮科医生魏小博/药物.md"};function o(n,a,s,h,f,d){return i(),l("div",null,a[0]||(a[0]=[r('<h1 id="药物" tabindex="-1">药物 <a class="header-anchor" href="#药物" aria-label="Permalink to &quot;药物&quot;">​</a></h1><h2 id="维a酸" tabindex="-1">维A酸 <a class="header-anchor" href="#维a酸" aria-label="Permalink to &quot;维A酸&quot;">​</a></h2><p>全能选手维A酸 黑头痘印都能去</p><h3 id="阿达帕林凝胶" tabindex="-1">阿达帕林凝胶<sup class="footnote-ref"><a href="#fn1" id="fnref1">[1]</a></sup> <a class="header-anchor" href="#阿达帕林凝胶" aria-label="Permalink to &quot;阿达帕林凝胶[^4]&quot;">​</a></h3><p><a href="https://www.zhihu.com/question/64456413/answer/1768882365" target="_blank" rel="noreferrer">更多详情</a></p><p>三代维A酸: 相较于第一代维A酸, 其光稳定性更好, 遇光更不易分解, 但还是尽量在<strong>晚上使用</strong></p><h4 id="阿达帕林凝胶-作用" tabindex="-1">阿达帕林凝胶-作用 <a class="header-anchor" href="#阿达帕林凝胶-作用" aria-label="Permalink to &quot;阿达帕林凝胶-作用&quot;">​</a></h4><ul><li>溶解粉剌</li><li>祛黑头</li><li>淡化痘印</li><li>一定程度收缩毛礼</li></ul><h4 id="阿达帕林凝胶-使用" tabindex="-1">阿达帕林凝胶-使用 <a class="header-anchor" href="#阿达帕林凝胶-使用" aria-label="Permalink to &quot;阿达帕林凝胶-使用&quot;">​</a></h4><h5 id="阿达帕林凝胶-建立耐受" tabindex="-1">阿达帕林凝胶-建立耐受<sup class="footnote-ref"><a href="#fn2" id="fnref2">[2]</a></sup> <a class="header-anchor" href="#阿达帕林凝胶-建立耐受" aria-label="Permalink to &quot;阿达帕林凝胶-建立耐受[^1]&quot;">​</a></h5><ol><li>第一天，涂在脸上停留5-10分钟后立刻清水洗掉；</li><li>第二天，停留时间可以放宽到15-20分钟；</li><li>以此类推，当停留超过1-2小时无任何不适时，可以不清洗，直接过夜；</li><li>前期如果感觉有轻微不适，可以暂且隐忍，如果有严重不适，需要立刻清洗停药；</li></ol><h4 id="阿达帕林凝胶-使用注意" tabindex="-1">阿达帕林凝胶-使用注意 <a class="header-anchor" href="#阿达帕林凝胶-使用注意" aria-label="Permalink to &quot;阿达帕林凝胶-使用注意&quot;">​</a></h4><ul><li>阿达帕林<strong>不能</strong>和过氧苯甲酰凝胶<strong>同时使用</strong></li><li>局部点涂 (因为有刺激性, 剥脱性)</li><li>刚用时有轻度的脱皮是正常的, 等时间长了<strong>建立耐受以后</strong>, 对于<strong>大面积的痘印</strong>或者<strong>鼻子上的黑头</strong>, 你就可以<strong>直接薄涂在上面</strong></li><li>最好<strong>晚上使用</strong>, 早上洗掉</li><li>不要涂在粘膜上</li></ul><h2 id="过氧苯甲酰凝胶" tabindex="-1">过氧苯甲酰凝胶 <a class="header-anchor" href="#过氧苯甲酰凝胶" aria-label="Permalink to &quot;过氧苯甲酰凝胶&quot;">​</a></h2><h3 id="过氧苯甲酰凝胶-作用" tabindex="-1">过氧苯甲酰凝胶-作用<sup class="footnote-ref"><a href="#fn1" id="fnref1:1">[1:1]</a></sup> <a class="header-anchor" href="#过氧苯甲酰凝胶-作用" aria-label="Permalink to &quot;过氧苯甲酰凝胶-作用[^4]&quot;">​</a></h3><ul><li>抑制毛囊口的过度角化 -&gt; 减少粉刺的形成</li><li>杀灭痤疮丙酸杆菌</li></ul><h3 id="过氧苯甲酰凝胶-适用" tabindex="-1">过氧苯甲酰凝胶-适用 <a class="header-anchor" href="#过氧苯甲酰凝胶-适用" aria-label="Permalink to &quot;过氧苯甲酰凝胶-适用&quot;">​</a></h3><ul><li>刚形成的粉刺</li><li>马上要冒痘的粉刺</li><li>有脓头的痘痘</li></ul><h3 id="过氧苯甲酰凝胶-使用注意" tabindex="-1">过氧苯甲酰凝胶-使用注意 <a class="header-anchor" href="#过氧苯甲酰凝胶-使用注意" aria-label="Permalink to &quot;过氧苯甲酰凝胶-使用注意&quot;">​</a></h3><ul><li>一天涂1到2次</li><li>局部点涂 (<strong>不可大面积揉</strong>)</li><li>有刺激性 (<strong>不要除抹到正常皮肤上</strong>)</li><li>可用水乳打底减轻刺激性</li><li>可与<a href="#抗生素">抗生素</a>联用 (减少抗生素的耐药性) 用法: 早上涂抗生素类, 晚上点过氧苯甲酰</li></ul><h2 id="抗生素" tabindex="-1">抗生素 <a class="header-anchor" href="#抗生素" aria-label="Permalink to &quot;抗生素&quot;">​</a></h2><p>(脓包克星抗生素 谨遵医嘱别乱用)</p><h3 id="夫西地酸乳膏" tabindex="-1">夫西地酸乳膏 <a class="header-anchor" href="#夫西地酸乳膏" aria-label="Permalink to &quot;夫西地酸乳膏&quot;">​</a></h3><h4 id="夫西地酸乳膏-适用" tabindex="-1">夫西地酸乳膏-适用 <a class="header-anchor" href="#夫西地酸乳膏-适用" aria-label="Permalink to &quot;夫西地酸乳膏-适用&quot;">​</a></h4><ul><li>丘疹型痘痘</li><li>脓疱型痘痘</li></ul><h4 id="夫西地酸乳膏-作用" tabindex="-1">夫西地酸乳膏-作用 <a class="header-anchor" href="#夫西地酸乳膏-作用" aria-label="Permalink to &quot;夫西地酸乳膏-作用&quot;">​</a></h4><ul><li>加速痘痘干瘪破裂</li><li>预防进一步感染</li><li>抑制痤疮丙酸杆菌以及葡萄球菌</li></ul><h4 id="夫西地酸乳膏-使用注意" tabindex="-1">夫西地酸乳膏-使用注意 <a class="header-anchor" href="#夫西地酸乳膏-使用注意" aria-label="Permalink to &quot;夫西地酸乳膏-使用注意&quot;">​</a></h4><ul><li>挤出来一点点, <strong>薄薄地涂在痘痘和痘痘边缘</strong>.</li></ul><p>&quot;注意这种就不要只点在痘痘上了, 因为我们<strong>尤其是痘痘破裂以后</strong>, 可能这个创口会引起其他细菌侵入, 造成二次感染. 所以我们涂这些破裂痘痘的话, 尽量在它的边缘也稍微带到一些.&quot;<sup class="footnote-ref"><a href="#fn3" id="fnref3">[3]</a></sup></p><h3 id="克林霉素" tabindex="-1">克林霉素 <a class="header-anchor" href="#克林霉素" aria-label="Permalink to &quot;克林霉素&quot;">​</a></h3><p>一直被认为是对痤疮丙酸杆菌抑制最好的一个外用抗生素</p><h4 id="如果使用夫西地酸效果不好的话可以试试它" tabindex="-1">如果使用夫西地酸效果不好的话可以试试它 <a class="header-anchor" href="#如果使用夫西地酸效果不好的话可以试试它" aria-label="Permalink to &quot;如果使用夫西地酸效果不好的话可以试试它&quot;">​</a></h4><h4 id="使用方法遇夫西地酸基本一样" tabindex="-1">使用方法遇夫西地酸基本一样 <a class="header-anchor" href="#使用方法遇夫西地酸基本一样" aria-label="Permalink to &quot;使用方法遇夫西地酸基本一样&quot;">​</a></h4><h3 id="克林霉素甲硝唑搽剂" tabindex="-1">克林霉素甲硝唑搽剂<sup class="footnote-ref"><a href="#fn4" id="fnref4">[4]</a></sup> <a class="header-anchor" href="#克林霉素甲硝唑搽剂" aria-label="Permalink to &quot;克林霉素甲硝唑搽剂[^2]&quot;">​</a></h3><ul><li>甲硝唑: 杀死螨虫</li><li>克林霉素: 杀灭痤疮丙酸杆菌</li></ul><h4 id="克林霉素甲硝唑搽剂-使用" tabindex="-1">克林霉素甲硝唑搽剂-使用 <a class="header-anchor" href="#克林霉素甲硝唑搽剂-使用" aria-label="Permalink to &quot;克林霉素甲硝唑搽剂-使用&quot;">​</a></h4><ul><li>点涂</li></ul><p>如果分不清自己脸上到底是什么感染引起的话, 那可以试试痤康王</p><hr class="footnotes-sep"><section class="footnotes"><ol class="footnotes-list"><li id="fn1" class="footnote-item"><p><a href="https://www.bilibili.com/video/BV1Av411b7LF" target="_blank" rel="noreferrer">阿达帕林、过氧苯甲酰，这些“网红”祛痘药究竟如何选择？</a> <a href="#fnref1" class="footnote-backref">↩︎</a> <a href="#fnref1:1" class="footnote-backref">↩︎</a></p></li><li id="fn2" class="footnote-item"><p><a href="https://www.zhihu.com/question/64456413/answer/1768882365" target="_blank" rel="noreferrer">瑞颜医生​​(第四军医大学 皮肤与性病学博士): 维a酸乳膏可以去痘印吗？</a> <a href="#fnref2" class="footnote-backref">↩︎</a></p></li><li id="fn3" class="footnote-item"><p><a href="https://www.bilibili.com/video/BV16w411i7iv" target="_blank" rel="noreferrer">乱买费钱！乱用烂脸！网红祛痘药膏，你真的用对了吗？</a> <a href="#fnref3" class="footnote-backref">↩︎</a></p></li><li id="fn4" class="footnote-item"><p><a href="https://www.bilibili.com/video/BV1kf4y1y7Ue" target="_blank" rel="noreferrer">医者难自医？一个皮肤科医生的自我祛痘经历！</a> <a href="#fnref4" class="footnote-backref">↩︎</a></p></li></ol></section>',41)]))}const b=e(t,[["render",o]]);export{u as __pageData,b as default};
